steps.code:
# Collect all song IDs from liked songs, liked albums, and liked playlists
all_song_ids = set()
for song in liked_songs:
    all_song_ids.add(song['song_id'])
for album in liked_albums:
    all_song_ids.update(album['song_ids'])
for playlist in liked_playlists:
    all_song_ids.update(playlist['song_ids'])
print("Total unique song IDs:", len(all_song_ids))
print(sorted(all_song_ids))

